//! Whether published prose says how its text came about, which the owner's own text never says.

/// The phrases, in small letters, that describe the writing instead of the change.
pub const PHRASES: [&str; 11] = [
    "ai-assisted",
    "ai assisted",
    "ai-generated",
    "ai generated",
    "generated by ai",
    "written by ai",
    "assisted by ai",
    "as an ai",
    "on behalf of the owner",
    "on the owner's behalf",
    "on the owner\u{2019}s behalf",
];

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum Verdict {
    Admit,
    Refuse,
}

/// A document that names how its text came about gets refused.
#[must_use]
pub const fn verdict(found: bool) -> Verdict {
    if found {
        Verdict::Refuse
    } else {
        Verdict::Admit
    }
}

pub const NEXT_ACTION: &str = "Rewrite that sentence about the change itself, in the owner's own voice, and send the text again.";

/// The one-based line and the phrase of the first provenance phrase in prose.
/// Fenced code blocks and inline code spans don't count, so a document can quote a phrase.
///
/// Exempt as disproportionate: an eleven-byte domain composes eleven phrase candidates at each position with UTF-8 line trimming and Markdown delimiter state.
/// The exhaustive enumeration covers three-byte prefixes of one eight-byte phrase.
/// Evidence: `crates/rules/src/provenance_rules.rs::tests::provenance_phrases_enumerate_every_short_markdown_prefix`.
/// Reconsider when the Markdown scan gives delimiter transitions their own contract apart from line trimming and phrase lookup.
#[must_use]
pub fn find(text: &str) -> Option<(usize, &'static str)> {
    let mut fenced = false;
    for (index, line) in text.lines().enumerate() {
        let trimmed = line.trim_start();
        if trimmed.starts_with("```") || trimmed.starts_with("~~~") {
            fenced = !fenced;
            continue;
        }
        if fenced {
            continue;
        }
        if let Some(phrase) = in_line(line.as_bytes()) {
            return Some((index + 1, phrase));
        }
    }
    None
}

/// The first phrase that starts a word outside an inline code span.
fn in_line(bytes: &[u8]) -> Option<&'static str> {
    let mut code = 0;
    let mut position = 0;
    while let Some(&byte) = bytes.get(position) {
        if byte == b'`' {
            let run = bytes.get(position..).map_or(1, |rest| {
                rest.iter().take_while(|&&next| next == b'`').count()
            });
            if code == 0 {
                code = run;
            } else if run == code {
                code = 0;
            }
            position += run;
            continue;
        }
        let starts_word = position == 0
            || bytes
                .get(position - 1)
                .is_none_or(|previous| !previous.is_ascii_alphanumeric());
        if code == 0 && starts_word {
            let found = PHRASES
                .iter()
                .find(|phrase| matches_at(bytes, position, phrase.as_bytes()));
            if found.is_some() {
                return found.copied();
            }
        }
        position += 1;
    }
    None
}

/// Whether `phrase` starts at `position`, in any letter case, and ends a word.
fn matches_at(bytes: &[u8], position: usize, phrase: &[u8]) -> bool {
    let end = position + phrase.len();
    bytes
        .get(position..end)
        .is_some_and(|candidate| candidate.eq_ignore_ascii_case(phrase))
        && bytes
            .get(end)
            .is_none_or(|next| !next.is_ascii_alphanumeric())
}

/// The properties Kani proves for every input and the tests check over every input they list.
#[cfg(any(test, kani))]
mod proofs {
    use super::*;

    #[cfg(test)]
    fn code_prefix(bytes: &[u8]) -> bool {
        let mut delimiter = 0;
        let mut run = 0;
        for &byte in bytes {
            if byte == b'`' {
                run += 1;
            } else if run != 0 {
                delimiter = if delimiter == 0 {
                    run
                } else if delimiter == run {
                    0
                } else {
                    delimiter
                };
                run = 0;
            }
        }
        if run != 0 {
            delimiter = if delimiter == 0 {
                run
            } else if delimiter == run {
                0
            } else {
                delimiter
            };
        }
        delimiter != 0
    }

    #[cfg(test)]
    fn reference_find(text: &str) -> Option<(usize, &'static str)> {
        let mut fenced = false;
        for (line_index, line) in text.lines().enumerate() {
            if line.trim_start().starts_with("```") || line.trim_start().starts_with("~~~") {
                fenced = !fenced;
                continue;
            }
            if fenced {
                continue;
            }
            let bytes = line.as_bytes();
            let mut first: Option<(usize, &str)> = None;
            for phrase in PHRASES {
                for (start, candidate) in bytes.windows(phrase.len()).enumerate() {
                    let boundary_before = start
                        .checked_sub(1)
                        .and_then(|index| bytes.get(index))
                        .is_none_or(|byte| !byte.is_ascii_alphanumeric());
                    let boundary_after = bytes
                        .get(start + phrase.len())
                        .is_none_or(|b| !b.is_ascii_alphanumeric());
                    if boundary_before
                        && boundary_after
                        && candidate.eq_ignore_ascii_case(phrase.as_bytes())
                        && bytes
                            .get(..start)
                            .is_some_and(|prefix| !code_prefix(prefix))
                        && first.is_none_or(|(earlier, _)| start < earlier)
                    {
                        first = Some((start, phrase));
                    }
                }
            }
            if let Some((_, phrase)) = first {
                return Some((line_index + 1, phrase));
            }
        }
        None
    }

    #[cfg(test)]
    pub fn spec_find(text: &str) -> bool {
        let actual = find(text);
        assert_eq!(actual, reference_find(text));
        actual.is_some()
    }

    pub fn spec_verdict(found: bool) {
        assert_eq!(verdict(found) == Verdict::Refuse, found);
    }

    #[cfg(kani)]
    #[kani::proof]
    fn only_a_found_phrase_is_refused() {
        let found: bool = kani::any();
        spec_verdict(found);
        kani::cover!(verdict(found) == Verdict::Refuse);
        kani::cover!(verdict(found) == Verdict::Admit);
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn provenance_phrases_enumerate_every_short_markdown_prefix() {
        for bytes in crate::domain::words(b"`~\nA ", 3) {
            let prefix = core::str::from_utf8(&bytes).unwrap();
            proofs::spec_find(&alloc::format!("{prefix}as an ai"));
        }
    }

    #[test]
    fn every_input_meets_the_specification() {
        for [found] in crate::domain::flags() {
            proofs::spec_verdict(found);
        }
        assert!(NEXT_ACTION.starts_with("Rewrite that sentence"));
    }

    #[test]
    fn each_phrase_is_found_in_prose_and_skipped_in_code() {
        for phrase in PHRASES {
            let upper = phrase.to_ascii_uppercase();
            for text in [
                alloc::format!("This change came {phrase}."),
                alloc::format!("Intro.\n\n{upper}, the parser keeps edits."),
            ] {
                assert_eq!(find(&text).map(|(_, found)| found), Some(phrase), "{text}");
            }
            assert_eq!(find(&alloc::format!("Quote `{phrase}` here.")), None);
            assert_eq!(
                find(&alloc::format!("Intro.\n```text\n{phrase}\n```\nOutro.")),
                None
            );
        }
        assert_eq!(
            find("One.\nTwo.\nAn AI-generated summary."),
            Some((3, "ai-generated"))
        );
    }

    #[test]
    fn ordinary_text_and_longer_words_pass() {
        for text in [
            "The parser keeps edits.",
            "The owner reviews releases.",
            "Agents meet dotfiles hooks.",
            "The AI-assistedness index stays.",
            "A chai assisted rewrite.",
            "",
        ] {
            assert_eq!(find(text), None, "{text}");
        }
    }
}
